        "customer",
        "month"
      ],
      "measures": [
        "orders",
        "otif_orders",
        "late_orders"
      ]
    },
    {
      "dataset": "maintenance_log",
      "description": "نگهداشت: پیشگیرانه در برابر اضطراری",
      "dimensions": [
        "machine",
        "month"
      ],
      "measures": [
        "pm_hours",
        "emergency_hours",
        "cost_m"
      ]
    },
    {
      "dataset": "equipment_oee",
      "description": "کارایی کلی تجهیزات به تفکیک ماشین",
      "dimensions": [
        "machine",
        "month"
      ],
      "measures": [
        "oee_pct",
        "availability_pct",
        "quality_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "otif",
      "description": "تحویل کامل به‌موقع",
      "formula": "سفارش‌های کامل به‌موقع تقسیم بر کل",
      "unit": "درصد",
      "dimensions": [
        "customer"
      ]
    },
    {
      "metric": "emergency_maintenance_ratio",
      "description": "سهم نگهداشت اضطراری",
      "formula": "ساعت اضطراری تقسیم بر کل ساعت نگهداشت",
      "unit": "درصد",
      "dimensions": [
        "machine"
      ]
    }
  ],
  "business_context": [
    "هدف تحویل کامل به‌موقع ۹۵٪ و کارایی تجهیزات ۷۵٪",
    "کارخانه با ۴ خط تولید و ۲ نوبت کاری",
    "دو مشتری سهم بیش از ۳۰٪ سفارش‌ها دارند"
  ]
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "otif"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}
```

نتیجهٔ داده:
```json
{
  "customer": "مشتری «پ»",
  "otif_pct": {
    "prev": 92.5,
    "curr": 70.8,
    "change_pp": -21.7
  }
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "maintenance_log",
    "filters": {
      "period": "curr_month"
    }
  }
}
```

ریشهٔ تحویل‌های دیر «مشتری «ب»» را تا انتها دنبال کن. (مدیر عملیات)

