--- داده‌های در دسترس (فقط همین‌ها مبنا هستند؛ عدد بیرون از این‌ها اختراع نشود) ---
```json
{
  "data_catalog": [
    {
      "dataset": "otif_delivery",
      "description": "تحویل کامل به‌موقع به مشتریان",
      "dimensions": [
        "customer",
        "month"
      ],
      "measures": [
        "orders",
        "otif_orders",
        "late_orders"
      ]
    },
    {
      "dataset": "maintenance_log",
      "description": "نگهداشت: پیشگیرانه در برابر اضطراری",
      "dimensions": [
        "machine",
        "month"
      ],
      "measures": [
        "pm_hours",
        "emergency_hours",
        "cost_m"
      ]
    },
    {
      "dataset": "production_output",
      "description": "تولید واقعی در برابر ظرفیت به تفکیک خط و ماه",
      "dimensions": [
        "line",
        "month"
      ],
      "measures": [
        "output_units",
        "capacity_units",
        "downtime_hours"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "otif",
      "description": "تحویل کامل به‌موقع",
      "formula": "سفارش‌های کامل به‌موقع تقسیم بر کل",
      "unit": "درصد",
      "dimensions": [
        "customer"
      ]
    },
    {
      "metric": "emergency_maintenance_ratio",
      "description": "سهم نگهداشت اضطراری",
      "formula": "ساعت اضطراری تقسیم بر کل ساعت نگهداشت",
      "unit": "درصد",
      "dimensions": [
        "machine"
      ]
    },
    {
      "metric": "oee",
      "description": "کارایی کلی تجهیزات",
      "formula": "دسترس‌پذیری × عملکرد × کیفیت",
      "unit": "درصد",
      "dimensions": [
        "machine"
      ]
    }
  ],
  "business_context": [
    "کارخانه با ۴ خط تولید و ۲ نوبت کاری",
    "هدف تحویل کامل به‌موقع ۹۵٪ و کارایی تجهیزات ۷۵٪",
    "ایمنی با شاخص رویدادهای نزدیک پایش می‌شود"
  ]
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "otif_delivery",
    "filters": {
      "customer": "مشتری «الف»",
      "period": "this_quarter"
    }
  }
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "maintenance_log",
    "filters": {
      "period": "this_quarter"
    }
  }
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "production_output",
    "filters": {
      "period": "this_quarter"
    }
  }
}
```

نتیجهٔ داده:
```json
{
  "peak_week_downtime_ratio": 2.0
}
```

